namespace sv_730e6105d3cb46409bd0aea5a029ed6c.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_730e6105d3cb46409bd0aea5a029ed6c.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="form-group avatar-group">
                        <label>Avatar</label>
                        <div class="avatar-preview">
                            <img src="@editProfile.AvatarUrl" alt="Avatar" onerror="this.style.display='none'" />
                        </div>
                        <span class="avatar-url">@editProfile.AvatarUrl</span>
                    </div>
                    <div class="form-group">
                        <label for="displayName">Display Name</label>
                        <input id="displayName" type="text" @bind="editProfile.DisplayName" />
                    </div>
                    <div class="form-group">
                        <label for="email">Email</label>
                        <input id="email" type="email" @bind="editProfile.Email" />
                    </div>
                    <div class="form-group">
                        <label for="bio">Bio</label>
                        <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile" disabled="@isSaving">
                            @(isSaving ? "Saving..." : "Save Changes")
                        </button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
                else
                {
                    <p class="loading">Loading profile...</p>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notificationPrefs is not null)
                {
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editNotifications.PushNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group">
                        <label>Muted Channels</label>
                        <div class="channel-list">
                            @foreach (var channel in editNotifications.MutedChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox" checked @onchange="(e) => ToggleMutedChannel(channel, e)" />
                                    <span>@channel (muted)</span>
                                </label>
                            }
                            @foreach (var channel in availableChannels.Where(c => !editNotifications.MutedChannels.Contains(c)))
                            {
                                <label class="channel-item">
                                    <input type="checkbox" @onchange="(e) => ToggleMutedChannel(channel, e)" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@isSaving">
                            @(isSaving ? "Saving..." : "Save Preferences")
                        </button>
                    </div>
                }
                else
                {
                    <p class="loading">Loading notification preferences...</p>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (securitySettings is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="ChangePassword" disabled="@isSaving">
                                    Update Password
                                </button>
                            </div>
                        }
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>
                                Two-Factor Authentication
                                <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                    @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </span>
                            <label class="switch">
                                <input type="checkbox" checked="@securitySettings.TwoFactorEnabled" disabled />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (securitySettings.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <div class="table-container">
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session.Id != currentSessionId)
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="current-session-badge">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>

                    @if (sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Confirm Session Revocation</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
                else
                {
                    <p class="loading">Loading security settings...</p>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearanceSettings is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(editAppearance.Theme == "Light")" @onchange='() => editAppearance.Theme = "Light"' />
                                <span>Light</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(editAppearance.Theme == "Dark")" @onchange='() => editAppearance.Theme = "Dark"' />
                                <span>Dark</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(editAppearance.Theme == "System")" @onchange='() => editAppearance.Theme = "System"' />
                                <span>System</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Small" checked="@(editAppearance.FontSize == "Small")" @onchange='() => editAppearance.FontSize = "Small"' />
                                <span>Small</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editAppearance.FontSize == "Medium")" @onchange='() => editAppearance.FontSize = "Medium"' />
                                <span>Medium</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Large" checked="@(editAppearance.FontSize == "Large")" @onchange='() => editAppearance.FontSize = "Large"' />
                                <span>Large</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editAppearance.Language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editAppearance.CompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <div class="form-group">
                        <label>Live Preview</label>
                        <div class="preview-area @GetPreviewClasses()">
                            <div class="preview-header">Preview Header</div>
                            <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Card content with your chosen theme and font size.</p>
                            </div>
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                            @(isSaving ? "Saving..." : "Save")
                        </button>
                    </div>
                }
                else
                {
                    <p class="loading">Loading appearance settings...</p>
                }
            </section>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isSaving;
    private string? toastMessage;
    private string toastType = "success";

    // Profile
    private UserProfile? profile;
    private EditableProfile editProfile = new();

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "random", "dev", "design", "marketing" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string currentSessionId = "current-session";
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearanceSettings;
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadCurrentSection();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        await LoadCurrentSection();
    }

    private async Task LoadCurrentSection()
    {
        switch (activeSection)
        {
            case "Profile":
                if (profile is null)
                {
                    profile = await SettingsService.GetProfileAsync();
                    MapProfileToEdit();
                }
                break;
            case "Notifications":
                if (notificationPrefs is null)
                {
                    notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    MapNotificationsToEdit();
                }
                break;
            case "Security":
                if (securitySettings is null)
                {
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    if (securitySettings.Sessions.Count > 0)
                        currentSessionId = securitySettings.Sessions[0].Id;
                }
                break;
            case "Appearance":
                if (appearanceSettings is null)
                {
                    appearanceSettings = await SettingsService.GetAppearanceAsync();
                    MapAppearanceToEdit();
                }
                break;
        }
    }

    // Profile methods
    private void MapProfileToEdit()
    {
        if (profile is null) return;
        editProfile = new EditableProfile
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };
    }

    private async Task SaveProfile()
    {
        isSaving = true;
        try
        {
            var updated = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            ShowToast("Profile saved successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving profile: {ex.Message}", "error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardProfileChanges()
    {
        MapProfileToEdit();
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void MapNotificationsToEdit()
    {
        if (notificationPrefs is null) return;
        editNotifications = new EditableNotifications
        {
            EmailNotifications = notificationPrefs.EmailNotifications,
            PushNotifications = notificationPrefs.PushNotifications,
            WeeklyDigest = notificationPrefs.WeeklyDigest,
            MutedChannels = new List<string>(notificationPrefs.MutedChannels)
        };
    }

    private void ToggleMutedChannel(string channel, ChangeEventArgs e)
    {
        var isMuted = (bool)(e.Value ?? false);
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        isSaving = true;
        try
        {
            var updated = new NotificationPrefs(
                editNotifications.EmailNotifications,
                editNotifications.PushNotifications,
                editNotifications.WeeklyDigest,
                new List<string>(editNotifications.MutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(updated);
            notificationPrefs = updated;
            ShowToast("Notification preferences saved!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving preferences: {ex.Message}", "error");
        }
        finally
        {
            isSaving = false;
        }
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || string.IsNullOrWhiteSpace(currentPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        isSaving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            showPasswordPanel = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error changing password: {ex.Message}", "error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked successfully.", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error revoking session: {ex.Message}", "error");
        }
        finally
        {
            sessionToRevoke = null;
        }
    }

    // Appearance methods
    private void MapAppearanceToEdit()
    {
        if (appearanceSettings is null) return;
        editAppearance = new EditableAppearance
        {
            Theme = appearanceSettings.Theme,
            FontSize = appearanceSettings.FontSize,
            Language = appearanceSettings.Language,
            CompactMode = appearanceSettings.CompactMode
        };
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        try
        {
            var updated = new AppearanceSettings(editAppearance.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            appearanceSettings = updated;
            ShowToast("Appearance settings saved!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving appearance: {ex.Message}", "error");
        }
        finally
        {
            isSaving = false;
        }
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = AutoDismissToast();
    }

    private async Task AutoDismissToast()
    {
        await Task.Delay(4000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => toastMessage = null;

    // Editable models for two-way binding
    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "en";
        public bool CompactMode { get; set; }
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.875rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: #555;
    transition: background 0.15s, color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    color: #212529;
}

.settings-section h3 {
    margin: 1.5rem 0 1rem;
    font-size: 1.15rem;
    color: #333;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.4rem;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

.form-group textarea {
    resize: vertical;
}

/* Avatar */
.avatar-group {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e0e0e0;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.5rem;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url {
    font-size: 0.8rem;
    color: #777;
    word-break: break-all;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switch */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex !important;
    justify-content: space-between;
    align-items: center;
    font-weight: normal !important;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    max-height: 200px;
    overflow-y: auto;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    cursor: pointer;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1.1rem;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Status indicator */
.status-indicator {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-left: 0.5rem;
}

.status-enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-disabled {
    background: #f8d7da;
    color: #842029;
}

/* Sessions table */
.table-container {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.sessions-table tr:hover {
    background: #f8f9fa;
}

.current-session-badge {
    display: inline-block;
    padding: 0.2rem 0.6rem;
    background: #e7f1ff;
    color: #0d6efd;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-weight: normal !important;
}

.radio-label input[type="radio"] {
    width: 16px;
    height: 16px;
}

/* Live preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s;
}

.preview-area.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.preview-theme-system {
    background: #f0f4f8;
    color: #333;
}

.preview-area.preview-font-small {
    font-size: 0.8rem;
}

.preview-area.preview-font-medium {
    font-size: 1rem;
}

.preview-area.preview-font-large {
    font-size: 1.2rem;
}

.preview-area.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.1em;
    margin-bottom: 0.5rem;
}

.preview-card {
    border: 1px solid currentColor;
    border-radius: 6px;
    padding: 0.75rem;
    margin-top: 0.75rem;
